 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    marker = next(( (r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 5), None)
    if marker is None:
        raise ValueError('missing marker')
    out = [[0]*7 for _ in range(h)]
    mr, mc = marker
    cursor = mc - 8
    out[mr][cursor] = 5

    # Follow the panels vertically on each side; each glyph writes a short
    # trace and shifts the horizontal cursor before the next panel.
    row = mr + 1
    for start_col in (0, 4):
        for top in range(0, h, 4):
            cells = [grid[r][c] for r in range(top, min(top+3,h))
                     for c in range(start_col, min(start_col+3,w))
                     if grid[r][c] not in (0,4,5)]
            if not cells:
                continue
            color = cells[0]
            if color == 1:
                for c in range(cursor, cursor+3):
                    if row < h and 0 <= c < 7: out[row][c] = 1
                cursor += 2
                row += 1
            elif color == 2:
                for c in range(cursor-1, cursor+1):
                    if row < h and 0 <= c < 7: out[row][c] = 2
                cursor -= 1
                row += 1
            elif color == 3:
                for c in range(cursor-3, cursor+1):
                    if row < h and 0 <= c < 7: out[row][c] = 3
                cursor -= 3
                row += 1
            elif color == 6:
                for rr in (row, row+1):
                    if rr < h and 0 <= cursor < 7: out[rr][cursor] = 6
                row += 2
    return out
